s\":{\"url_path\":\"/en/library/bg/12/5/\",\"title\":\"TEXT 5\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/12/8/\",\"title\":\"TEXT 8\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3513,\"bb\":568338,\"url_path\":\"/en/library/bg/12/6-7/devanagari/\",\"body_final\":\"ये तु सर्वाणि कर्माणि मयि सन्न्यस्य मत्परा: ।
अनन्येनैव योगेन मां ध्यायन्त उपासते ॥ ६ ॥
तेषामहं समुद्धर्ता मृत्युसंसारसागरात् ।
भवामि न चिरात्पार्थ मय्यावेशितचेतसाम् ॥ ७ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3514,\"bb\":3096,\"url_path\":\"/en/library/bg/12/6-7/b3096/\",\"body_value\":\"ye tu sarvāṇi karmāṇi
mayi sannyasya mat-parāḥ
ananyenaiva yogena
māṁ dhyāyanta upāsate\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3515,\"bb\":3097,\"url_path\":\"/en/library/bg/12/6-7/b3097/\",\"body_value\":\"teṣām ahaṁ samuddhartā
mṛtyu-saṁsāra-sāgarāt
bhavāmi na cirāt pārtha
mayy āveśita-cetasām\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3516,\"bb\":3098,\"url_path\":\"/en/library/bg/12/6-7/b3098/\",\"shadow_value\":\"ye – those who; tu – but; sarvāṇi – all; karmāṇi – activities; mayi – unto Me; sannyasya – giving up; mat-parāḥ – being attached to Me; ananyena – without division; eva – certainly; yogena – by practice of such bhakti-yoga; mām – upon Me; dhyāyantaḥ – meditating; upāsate – worship; teṣām – of them; aham – I; samuddhartā – the deliverer; mṛtyu – of death; saṁsāra – in material existence; sāgarāt – from the ocean; bhavāmi – I become; na – not; cirāt – after a long time; pārtha – O son of Pṛthā; mayi – upon Me; āveśita – fixed; cetasām – of those whose minds.\",\"word_for_word_value\":[{\"word\":\"ye\",\"translation\":\"those who\"},{\"word\":\"tu\",\"translation\":\"but\"},{\"word\":\"sarvāṇi\",\"translation\":\"all\"},{\"word\":\"karmāṇi\",\"translation\":\"activities\"},{\"word\":\"mayi\",\"translation\":\"unto Me\"},{\"word\":\"sannyasya\",\"translation\":\"giving up\"},{\"word\":\"mat-parāḥ\",\"translation\":\"being attached to Me\"},{\"word\":\"ananyena\",\"translation\":\"without division\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"yogena\",\"translation\":\"by practice of such bhakti-yoga\"},{\"word\":\"mām\",\"translation\":\"upon Me\"},{\"word\":\"dhyāyantaḥ\",\"translation\":\"meditating\"},{\"word\":\"upāsate\",\"translation\":\"worship\"},{\"word\":\"teṣām\",\"translation\":\"of them\"},{\"word\":\"aham\",\"translation\":\"I\"},{\"word\":\"samuddhartā\",\"translation\":\"the deliverer\"},{\"word\":\"mṛtyu\",\"translation\":\"of death\"},{\"word\":\"saṁsāra\",\"translation\":\"in material existence\"},{\"word\":\"sāgarāt\",\"translation\":\"from the ocean\"},{\"word\":\"bhavāmi\",\"translation\":\"I become\"},{\"word\":\"na\",\"translation\":\"not\"},{\"word\":\"cirāt\",\"translation\":\"after a long time\"},{\"word\":\"pārtha\",\"translation\":\"O son of Pṛthā\"},{\"word\":\"mayi\",\"translation\":\"upon Me\"},{\"word\":\"āveśita\",\"translation\":\"fixed\"},{\"word\":\"cetasām\",\"translation\":\"of those whose minds\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3517,\"bb\":3099,\"url_path\":\"/en/library/bg/12/6-7/b3099/\",\"body_value\":\"But those who worship Me, giving up all their activities unto Me and being devoted to Me without deviation, engaged in devotional service and always meditating upon Me, having fixed their minds upon Me, O son of Pṛthā – for them I am the swift deliverer from the ocean of birth and death.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3518,\"bb\":3100,\"url_path\":\"/en/library/bg/12/6-7/b3100/\",\"body_value\":\"It is explicitly stated here that the devotees are very fortunate to be delivered very soon from material existence by the Lord. In pure devotional service one comes to the realization that God is great and that the individual soul is subordinate to Him. His duty is to render service to the Lord – and if he does not, then he will render service to māyā.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3519,\"bb\":3101,\"url_path\":\"/en/library/bg/12/6-7/b3101/\",\"body_value\":\"As stated before, the Supreme Lord can be appreciated only by devotional service. Therefore, one should be fully devoted. One should fix his mind fully on Kṛṣṇa in order to achieve Him. One should work only for Kṛṣṇa. It does not matter in what kind of work one engages, but that work should be done only for Kṛṣṇa. That is the standard of devotional service. The devotee does not desire any achievement other than pleasing the Supreme Personality of Godhead. His life’s mission is to please Kṛṣṇa, and he can sacrifice everything for Kṛṣṇa’s satisfaction, just as Arjuna did in the Battle of Kurukṣetra. The process is very simple: one can devote himself in his occupation and engage at the same time in chanting Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare. Such transcendental chanting attracts the devotee to the Personality of Godhead.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3520,\"bb\":3102,\"url_path\":\"/en/library/bg/12/6-7/b3102/\",\"body_value\":\"The Supreme Lord herein promises that without delay He will deliver a pure devotee thus engaged from the ocean of material existence. Those who are advanced in yoga practice can willfully transfer the soul to whatever planet they like by the yoga process, and others take the opportunity in various ways, but as far as the devotee is concerned, it is clearly stated here that the Lord Himself takes him. The devotee does not need to wait to become very experienced in order to transfer himself to the spiritual sky.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3521,\"bb\":3103,\"url_path\":\"/en/library/bg/12/6-7/b3103/\",\"body_value\":\"In the Varāha Purāṇa this verse appears:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3522,\"bb\":3104,\"url_path\":\"/en/library/bg/12/6-7/b3104/\",\"body_value\":\"nayāmi paramaṁ sthānam
arcir-ādi-gatiṁ vinā
garuḍa-skandham āropya
yatheccham anivāritaḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3523,\"bb\":3105,\"url_path\":\"/en/library/bg/12/6-7/b3105/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3524,\"bb\":3106,\"url_path\":\"/en/library/bg/12/6-7/b3106/\",\"body_value\":\"yā vai sādhana-sampattiḥ
puruṣārtha-catuṣṭaye
tayā vinā tad āpnoti
naro nārāyaṇāśrayaḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3525,\"bb\":3107,\"url_path\":\"/en/library/bg/12/6-7/b3107/\",\"body_value\":\"The purport of this verse is that one should not engage in the different processes of fruitive activity or cultivate knowledge by the mental speculative process. One who is devoted to the Supreme Personality can attain all the benefits derived from other yogic processes, speculation, rituals, sacrifices, charities, etc. That is the specific benediction of devotional service.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3526,\"bb\":3108,\"url_path\":\"/en/library/bg/12/6-7/b3108/\",\"body_value\":\"Simply by chanting the holy name of Kṛṣṇa – Hare Kṛṣṇa, Hare Kṛṣṇa, Kṛṣṇa Kṛṣṇa, Hare Hare/ Hare Rāma, Hare Rāma, Rāma Rāma, Hare Hare – a devotee of the Lord can approach the supreme destination easily and happily, but this destination cannot be approached by any other process of religion.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3527,\"bb\":3109,\"url_path\":\"/en/library/bg/12/6-7/b3109/\",\"body_value\":\"The conclusion of Bhagavad-gītā is stated in the Eighteenth Chapter:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3528,\"bb\":3110,\"url_path\":\"/en/library/bg/12/6-7/b3110/\",\"body_value\":\"sarva-dharmān parityajya
mām ekaṁ śaraṇaṁ vraja
ahaṁ tvāṁ sarva-pāpebhyo
mokṣayiṣyāmi mā śucaḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3529,\"bb\":3111,\"url_path\":\"/en/library/bg/12/6-7/b3111/\",\"body_value\":\"One should give up all other processes of self-realization and simply execute devotional service in Kṛṣṇa consciousness. That will enable one to reach the highest perfection of life. There is no need for one to consider the sinful actions of his past life, because the Supreme Lord fully takes charge of him. Therefore one should not futilely try to deliver himself in spiritual realization. Let everyone take shelter of the supreme omnipotent Godhead, Kṛṣṇa. That is the highest perfection of life.\"}]}],\"short_title\":\"Bg. 12.6-7\",\"medium_title\":\"Bhagavad-gītā As It Is 12.6-7\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"childre